  posX: f32,
  posY: f32,
  velX: f32,
  velY: f32,
  colorR: f32,
  colorG: f32,
  colorB: f32,
  colorA: f32,
  size: f32,
  rotation: f32,
  life: f32,
  maxLife: f32,
  startSize: f32,
  endSize: f32,
  startRot: f32,
  endRot: f32,
  startR: f32,
  startG: f32,
  startB: f32,
  startA: f32,
  endR: f32,
  endG: f32,
  endB: f32,
  endA: f32,
